use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// Simple counting semaphore (for the two coordination permits sa and sb).
struct Semaphore {
    count: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(initial: usize) -> Self {
        Semaphore {
            count: Mutex::new(initial),
            cv: Condvar::new(),
        }
    }

